{"file_path":"src/parser.js","content":"/**
 * Parser for the configuration document format described in the task.
 *
 * The document is parsed line by line (every directive fits on one line)
 * into a tree of Node objects:
 *
 *   { type: 'table', entries: Map<string, Node>, headerTargeted: boolean }
 *   { type: 'array-of-tables', items: Node[] }   // items are 'table' nodes
 *   { type: 'array', items: Node[] }
 *   { type: 'string', value: string }
 *   { type: 'integer', text: string }            // normalized digit text
 *   { type: 'float', value: number }
 *   { type: 'boolean', value: boolean }
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function makeTable() {
  return { type: 'table', entries: new Map(), headerTargeted: false }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(\.\d+(?:_\d+)*)?([eE][+-]?\d+(?:_\d+)*)?$/

function skipWS(raw, pos) {
  while (pos < raw.length && (raw[pos] === ' ' || raw[pos] === '\t')) pos++
  return pos
}

// Skip whitespace; if what follows is a comment marker, report the position
// as end-of-line since everything from there on is ignored.
function effectivePos(raw, pos) {
  pos = skipWS(raw, pos)
  if (pos < raw.length && (raw[pos] === '#' || raw[pos] === ';')) return raw.length
  return pos
}

function normalizeInt(token) {
  let text = token.replace(/_/g, '')
  if (text[0] === '+') text = text.slice(1)
  return text
}

function classifyBareToken(token) {
  if (token === 'true') return { type: 'boolean', value: true }
  if (token === 'false') return { type: 'boolean', value: false }
  if (INT_RE.test(token)) return { type: 'integer', text: normalizeInt(token) }
  const m = FLOAT_RE.exec(token)
  if (m && (m[1] || m[2])) return { type: 'float', value: Number(token.replace(/_/g, '')) }
  return null
}

// Parses a basic (double-quoted) or literal (single-quoted) string starting
// at `pos`, which must point at the opening quote character.
function parseStringLiteral(raw, pos, lineNo) {
  const quote = raw[pos]
  pos++
  let out = ''
  if (quote === "'") {
    while (true) {
      if (pos >= raw.length) fail(lineNo, 'unterminated string')
      const ch = raw[pos]
      if (ch === "'") return { value: out, pos: pos + 1 }
      out += ch
      pos++
    }
  }
  while (true) {
    if (pos >= raw.length) fail(lineNo, 'unterminated string')
    const ch = raw[pos]
    if (ch === '"') return { value: out, pos: pos + 1 }
    if (ch === '\\') {
      pos++
      if (pos >= raw.length) fail(lineNo, 'unterminated string')
      const esc = raw[pos]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (esc === 'u') {
        const hex = raw.slice(pos + 1, pos + 5)
        if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) fail(lineNo, 'invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        pos += 5
      } else if (Object.prototype.hasOwnProperty.call(simple, esc)) {
        out += simple[esc]
        pos++
      } else {
        fail(lineNo, `invalid escape \\${esc}`)
      }
    } else {
      out += ch
      pos++
    }
  }
}

// Parses a name (bare word or quoted string) at `pos`.
function parseName(raw, pos, lineNo) {
  if (pos >= raw.length) fail(lineNo, 'expected a name')
  const ch = raw[pos]
  if (ch === '"' || ch === "'") {
    const { value, pos: next } = parseStringLiteral(raw, pos, lineNo)
    return { name: value, pos: next }
  }
  let end = pos
  while (end < raw.length && NAME_CHAR.test(raw[end])) end++
  if (end === pos) fail(lineNo, 'expected a name')
  return { name: raw.slice(pos, end), pos: end }
}

// Parses a dotted name: name ('.' name)*
function parseDottedName(raw, pos, lineNo) {
  const segments = []
  let { name, pos: p } = parseName(raw, pos, lineNo)
  segments.push(name)
  p = skipWS(raw, p)
  while (p < raw.length && raw[p] === '.') {
    p = skipWS(raw, p + 1)
    ;({ name, pos: p } = parseName(raw, p, lineNo))
    segments.push(name)
    p = skipWS(raw, p)
  }
  return { segments, pos: p }
}

// Walks `segments` inside `table`, creating intermediate tables as needed,
// and assigns `valueNode` at the final segment. `prefixPath` is the dotted
// path (as an array of decoded name strings) leading to `table` itself.
function assignDotted(table, prefixPath, segments, valueNode, lineNo) {
  let node = table
  const pathSoFar = prefixPath.slice()
  for (let k = 0; k < segments.length - 1; k++) {
    const seg = segments[k]
    pathSoFar.push(seg)
    const existing = node.entries.get(seg)
    if (existing === undefined) {
      const t = makeTable()
      node.entries.set(seg, t)
      node = t
    } else if (existing.type === 'table') {
      node = existing
    } else if (existing.type === 'array-of-tables') {
      node = existing.items[existing.items.length - 1]
    } else {
      fail(lineNo, `${pathSoFar.join('.')} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  pathSoFar.push(last)
  if (node.entries.has(last)) fail(lineNo, `key ${pathSoFar.join('.')} is defined twice`)
  node.entries.set(last, valueNode)
}

// Parses a value at `pos`. `path` is the dotted path (array of strings) that
// this value is being assigned to, used only so nested inline tables can
// build correct paths for their own duplicate-key errors.
function parseValue(raw, pos, lineNo, path) {
  pos = effectivePos(raw, pos)
  if (pos >= raw.length) fail(lineNo, 'expected a value')
  const ch = raw[pos]
  if (ch === ',' || ch === ']' || ch === '}') fail(lineNo, 'expected a value')
  if (ch === '"' || ch === "'") {
    const { value, pos: next } = parseStringLiteral(raw, pos, lineNo)
    return { node: { type: 'string', value }, pos: next }
  }
  if (ch === '[') return parseArray(raw, pos, lineNo, path)
  if (ch === '{') return parseInlineTable(raw, pos, lineNo, path)
  let end = pos
  while (end < raw.length && raw[end] !== ' ' && raw[end] !== '\t' && raw[end] !== ',' && raw[end] !== ']' && raw[end] !== '}') {
    end++
  }
  const token = raw.slice(pos, end)
  const classified = classifyBareToken(token)
  if (!classified) fail(lineNo, `invalid value ${token}`)
  return { node: classified, pos: end }
}

function parseArray(raw, pos, lineNo, path) {
  pos++ // consume '['
  const items = []
  pos = effectivePos(raw, pos)
  if (pos < raw.length && raw[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
  while (true) {
    if (pos >= raw.length) fail(lineNo, 'expected a value')
    const { node, pos: p1 } = parseValue(raw, pos, lineNo, path)
    items.push(node)
    pos = effectivePos(raw, p1)
    if (pos >= raw.length) fail(lineNo, 'unterminated array')
    if (raw[pos] === ',') {
      pos = effectivePos(raw, pos + 1)
      if (pos < raw.length && raw[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
      if (pos >= raw.length) fail(lineNo, 'expected a value')
      continue
    }
    if (raw[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
    fail(lineNo, 'unterminated array')
  }
}

function parseInlineTable(raw, pos, lineNo, path) {
  pos++ // consume '{'
  const table = makeTable()
  pos = effectivePos(raw, pos)
  if (pos < raw.length && raw[pos] === '}') return { node: table, pos: pos + 1 }
  while (true) {
    pos = effectivePos(raw, pos)
    if (pos >= raw.length) fail(lineNo, 'unterminated inline table')
    const ch = raw[pos]
    if (!(ch === '"' || ch === "'" || NAME_CHAR.test(ch))) fail(lineNo, 'expected a name')
    const { segments, pos: p1 } = parseDottedName(raw, pos, lineNo)
    pos = effectivePos(raw, p1)
    if (pos >= raw.length || raw[pos] !== '=') fail(lineNo, 'expected = in an inline table')
    pos = effectivePos(raw, pos + 1)
    const fullPath = path.concat(segments)
    const { node: value, pos: p2 } = parseValue(raw, pos, lineNo, fullPath)
    assignDotted(table, path, segments, value, lineNo)
    pos = effectivePos(raw, p2)
    if (pos >= raw.length) fail(lineNo, 'unterminated inline table')
    if (raw[pos] === ',') {
      pos++
      continue
    }
    if (raw[pos] === '}') return { node: table, pos: pos + 1 }
    fail(lineNo, 'unterminated inline table')
  }
}

function resolveHeaderPath(root, segments, isArrayHeader, lineNo) {
  let node = root
  const pathSoFar = []
  for (let k = 0; k < segments.length - 1; k++) {
    const seg = segments[k]
    pathSoFar.push(seg)
    const existing = node.entries.get(seg)
    if (existing === undefined) {
      const t = makeTable()
      node.entries.set(seg, t)
      node = t
    } else if (existing.type === 'table') {
      node = existing
    } else if (existing.type === 'array-of-tables') {
      node = existing.items[existing.items.length - 1]
    } else {
      fail(lineNo, `${pathSoFar.join('.')} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  pathSoFar.push(last)
  const existing = node.entries.get(last)
  if (!isArrayHeader) {
    if (existing === undefined) {
      const t = makeTable()
      t.headerTargeted = true
      node.entries.set(last, t)
      return { current: t, path: pathSoFar }
    }
    if (existing.type === 'table') {
      if (existing.headerTargeted) fail(lineNo, `table ${pathSoFar.join('.')} is defined twice`)
      existing.headerTargeted = true
      return { current: existing, path: pathSoFar }
    }
    fail(lineNo, `${pathSoFar.join('.')} is not a table`)
  } else {
    if (existing === undefined) {
      const arr = { type: 'array-of-tables', items: [] }
      node.entries.set(last, arr)
      const t = makeTable()
      arr.items.push(t)
      return { current: t, path: pathSoFar }
    }
    if (existing.type === 'array-of-tables') {
      const t = makeTable()
      existing.items.push(t)
      return { current: t, path: pathSoFar }
    }
    fail(lineNo, `${pathSoFar.join('.')} is not an array of tables`)
  }
}

function parseHeaderLine(raw, i, lineNo, root) {
  const isArrayHeader = raw[i + 1] === '['
  let pos = i + (isArrayHeader ? 2 : 1)
  pos = skipWS(raw, pos)
  const { segments, pos: p1 } = parseDottedName(raw, pos, lineNo)
  pos = p1
  if (pos >= raw.length || raw[pos] !== ']') fail(lineNo, 'unterminated table header')
  pos++
  if (isArrayHeader) {
    if (pos >= raw.length || raw[pos] !== ']') fail(lineNo, 'unterminated table header')
    pos++
  }
  pos = effectivePos(raw, pos)
  if (pos < raw.length) fail(lineNo, 'trailing text after a table header')
  return resolveHeaderPath(root, segments, isArrayHeader, lineNo)
}

function parseKeyValueLine(raw, i, lineNo, current, currentPath) {
  const { segments, pos: p1 } = parseDottedName(raw, i, lineNo)
  let pos = p1
  if (pos >= raw.length || raw[pos] !== '=') fail(lineNo, 'expected key = value')
  pos = effectivePos(raw, pos + 1)
  const fullPath = currentPath.concat(segments)
  const { node: value, pos: p2 } = parseValue(raw, pos, lineNo, fullPath)
  pos = effectivePos(raw, p2)
  if (pos < raw.length) fail(lineNo, 'trailing text after a value')
  assignDotted(current, currentPath, segments, value, lineNo)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let current = root
  let currentPath = []

  for (let li = 0; li < lines.length; li++) {
    const raw = lines[li]
    const lineNo = li + 1
    let i = 0
    while (i < raw.length && (raw[i] === ' ' || raw[i] === '\t')) i++
    if (i >= raw.length) continue
    if (raw[i] === '#' || raw[i] === ';') continue

    if (raw[i] === '[') {
      const result = parseHeaderLine(raw, i, lineNo, root)
      current = result.current
      currentPath = result.path
    } else {
      parseKeyValueLine(raw, i, lineNo, current, currentPath)
    }
  }

  return root
}
"}

