  let out = ''
  if (quote === "'") {
    while (true) {
      if (pos >= raw.length) fail(lineNo, 'unterminated string')
      const ch = raw[pos]
      if (ch === "'") return { value: out, pos: pos + 1 }
      out += ch
      pos++
    }
  }
  while (true) {
    if (pos >= raw.length) fail(lineNo, 'unterminated string')
    const ch = raw[pos]
    if (ch === '"') return { value: out, pos: pos + 1 }
    if (ch === '\\') {
      pos++
      if (pos >= raw.length) fail(lineNo, 'unterminated string')
      const esc = raw[pos]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (esc === 'u') {
        const hex = raw.slice(pos + 1, pos + 5)
        if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) fail(lineNo, 'invalid escape \\u')
