// Parses a name (bare word or quoted string) at `pos`.
function parseName(raw, pos, lineNo) {
  if (pos >= raw.length) fail(lineNo, 'expected a name')
  const ch = raw[pos]
  if (ch === '"' || ch === "'") {
    const { value, pos: next } = parseStringLiteral(raw, pos, lineNo)
    return { name: value, pos: next }
