  }
}

function resolveHeaderPath(root, segments, isArrayHeader, lineNo) {
  let node = root
  const pathSoFar = []
  for (let k = 0; k < segments.length - 1; k++) {
    const seg = segments[k]
    pathSoFar.push(seg)
    const existing = node.entries.get(seg)
    if (existing === undefined) {
      const t = makeTable()
      node.entries.set(seg, t)
      node = t
    } else if (existing.type === 'table') {
      node = existing
    } else if (existing.type === 'array-of-tables') {
      node = existing.items[existing.items.length - 1]
    } else {
      fail(lineNo, `${pathSoFar.join('.')} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  pathSoFar.push(last)
  const existing = node.entries.get(last)
  if (!isArrayHeader) {
    if (existing === undefined) {
      const t = makeTable()
      t.headerTargeted = true
      node.entries.set(last, t)
      return { current: t, path: pathSoFar }
    }
    if (existing.type === 'table') {
      if (existing.headerTargeted) fail(lineNo, `table ${pathSoFar.join('.')} is defined twice`)
      existing.headerTargeted = true
      return { current: existing, path: pathSoFar }
    }
    fail(lineNo, `${pathSoFar.join('.')} is not a table`)
  } else {
    if (existing === undefined) {
      const arr = { type: 'array-of-tables', items: [] }
      node.entries.set(last, arr)
      const t = makeTable()
      arr.items.push(t)
      return { current: t, path: pathSoFar }
    }
    if (existing.type === 'array-of-tables') {
      const t = makeTable()
      existing.items.push(t)
      return { current: t, path: pathSoFar }
    }
    fail(lineNo, `${pathSoFar.join('.')} is not an array of tables`)
  }
}

function parseHeaderLine(raw, i, lineNo, root) {
  const isArrayHeader = raw[i + 1] === '['
  let pos = i + (isArrayHeader ? 2 : 1)
  pos = skipWS(raw, pos)
  const { segments, pos: p1 } = parseDottedName(raw, pos, lineNo)
  pos = p1
  if (pos >= raw.length || raw[pos] !== ']') fail(lineNo, 'unterminated table header')
  pos++
  if (isArrayHeader) {
    if (pos >= raw.length || raw[pos] !== ']') fail(lineNo, 'unterminated table header')
    pos++
  }
  pos = effectivePos(raw, pos)
  if (pos < raw.length) fail(lineNo, 'trailing text after a table header')
  return resolveHeaderPath(root, segments, isArrayHeader, lineNo)
}

function parseKeyValueLine(raw, i, lineNo, current, currentPath) {
  const { segments, pos: p1 } = parseDottedName(raw, i, lineNo)
  let pos = p1
  if (pos >= raw.length || raw[pos] !== '=') fail(lineNo, 'expected key = value')
  pos = effectivePos(raw, pos + 1)
  const fullPath = currentPath.concat(segments)
  const { node: value, pos: p2 } = parseValue(raw, pos, lineNo, fullPath)
  pos = effectivePos(raw, p2)
  if (pos < raw.length) fail(lineNo, 'trailing text after a value')
  assignDotted(current, currentPath, segments, value, lineNo)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let current = root
  let currentPath = []

  for (let li = 0; li < lines.length; li++) {
    const raw = lines[li]
    const lineNo = li + 1
    let i = 0
    while (i < raw.length && (raw[i] === ' ' || raw[i] === '\t')) i++
    if (i >= raw.length) continue
    if (raw[i] === '#' || raw[i] === ';') continue

    if (raw[i] === '[') {
      const result = parseHeaderLine(raw, i, lineNo, root)
      current = result.current
      currentPath = result.path
    } else {
      parseKeyValueLine(raw, i, lineNo, current, currentPath)
    }
  }

  return root
}
