// Compares strings in ascending order by Unicode code point, which differs
// from plain JS string comparison (UTF-16 code units) for astral characters.
function compareCodePoint(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const x = ca[i].codePointAt(0)
    const y = cb[i].codePointAt(0)
    if (x !== y) return x - y
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return Array.from(table.entries.keys()).sort(compareCodePoint)
}

function serialize(node, indent) {
  switch (node.type) {
    case 'boolean':
      return String(node.value)
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    case 'string':
      return JSON.stringify(node.value)
    case 'array':
    case 'array-of-tables': {
      const items = node.items
      if (items.length === 0) return '[]'
      const childIndent = indent + '  '
      const inner = items.map((it) => childIndent + serialize(it, childIndent)).join(',\n')
      return '[\n' + inner + '\n' + indent + ']'
    }
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const childIndent = indent + '  '
      const inner = keys
        .map((k) => childIndent + JSON.stringify(k) + ': ' + serialize(node.entries.get(k), childIndent))
        .join(',\n')
      return '{\n' + inner + '\n' + indent + '}'
    }
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

export function toJSON(root) {
  return serialize(root, '') + '\n'
}

function typeLabel(node) {
  switch (node.type) {
    case 'table':
      return 'table'
    case 'array':
    case 'array-of-tables':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function walk(node, path, out) {
  if (node.type === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.entries.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeLabel(child)}`)
      walk(child, childPath, out)
    }
