      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${typeLabel(item)}`)
      walk(item, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
