{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { toJSON, toKeys } from './format.js'

const args = process.argv.slice(2)
const mode = args[0]

if (args.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let input
try {
  input = fs.readFileSync(0, 'utf8')
} catch {
  input = ''
}

try {
  const root = parseDocument(input)
  const output = mode === 'json' ? toJSON(root) : toKeys(root)
  process.stdout.write(output)
  process.exit(0)
} catch (err) {
  if (err instanceof ParseError) {
    process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
    process.exit(2)
  }
  throw err
}
"}

